starts=[1,8,15,22]
symbols=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for tr,y in enumerate(starts):
    for tc,x in enumerate(starts):
        for dy in range(5):
            for dx in range(5):
                g[y+dy][x+dx]=4 if dy in (0,4) or dx in (0,4) else symbols[tr][tc]
# bottom partial fifth tile border row at y=29 (visible in input)
for x in starts:
    for dx in range(5): g[29][x+dx]=4
# rightmost partial tile border column x=29, visible at y1..29
for y in starts:
    for dy in range(5): g[y+dy][29]=4
# Draw connections between matching symbols for each row/column; alter only separator cells.
# Horizontal at each tile row's center line
for tr,y in enumerate(starts):
    cy=y+2
    for color in set(symbols[tr]):
        inds=[i for i,v in enumerate(symbols[tr]) if v==color]
        for a,b in zip(inds,inds[1:]):
            for tc in range(a,b):
                # gap between tile tc and next
                for x in (starts[tc]+5, starts[tc]+6): g[cy][x]=color
# Vertical at each tile column center line
for tc,x in enumerate(starts):
    cx=x+2
    vals=[symbols[tr][tc] for tr in range(4)]
    for color in set(vals):
        inds=[i for i,v in enumerate(vals) if v==color]
        for a,b in zip(inds,inds[1:]):
            for tr in range(a,b):
                for y in (starts[tr]+5, starts[tr]+6): g[y][cx]=color
print('\n'.join(' '.join(map(str,r)) for r in g))

